// Retorna confirmação da movimentação
const resposta = $json.data || $json;

if (!resposta || resposta.status === 'error') {
  return {
    sucesso: false,
    mensagem: resposta?.message || 'Erro ao registrar movimentação'
  };
}

const tipo_texto = $json.tipo === 'RETIRADA' ? 'retirada' : 'devolução';
const quantidade_texto = $json.quantidade === 1 ? 'peça' : 'peças';

return {
  sucesso: true,
  movimentacao_id: resposta.id,
  contrato_id: resposta.contrato_id,
  tipo: resposta.tipo,
  quantidade: resposta.quantidade,
  data: resposta.data,
  quantidade_atual: resposta.quantidade_atual,
  mensagem: `${tipo_texto.charAt(0).toUpperCase() + tipo_texto.slice(1)} de ${resposta.quantidade} ${quantidade_texto} registrada com sucesso! Quantidade atual: ${resposta.quantidade_atual}`
};
